insert into public.settings(key, value) values ('store_name', '"Prompt2Print"'), ('currency', '"SAR"'), ('default_country', '"SA"'), ('wall_thickness_mm', '2.1'), ('min_wall_mm', '2'), ('infill_range', '[30,40]'), ('fee_tiers', '[{"maxCents":37500,"percent":15},{"maxCents":null,"percent":5}]'), ('ai_provider', '"auto"'), ('ai_hourly_limit', '30'), ('ai_default_size_mm', '100'), ('payment_provider', '"tap"'), ('max_model_mm', '250'), ('fallback_currency', '"USD"') on conflict (key) do update set value = excluded.value;
