insert into public.categories(slug, name_en, name_ar, sort) values ('desk', 'Desk & office', 'المكتب', 0), ('decor', 'Home decor', 'ديكور المنزل', 1), ('plants', 'Planters', 'أحواض الزرع', 2), ('organizers', 'Organizers & holders', 'منظّمات وحوامل', 3), ('chess', 'Chess & games', 'الشطرنج والألعاب', 4), ('figurines', 'Figurines & art', 'مجسمات وفنون', 5), ('gifts', 'Gifts & keychains', 'هدايا وميداليات', 6) on conflict (slug) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, sort = excluded.sort;
insert into public.materials(code, name_en, name_ar, desc_en, desc_ar, price_per_gram, density, process, nozzle_temp, bed_temp, max_temp_c, colors, sort) values ('ABS', 'ABS', 'ABS', 'Tough and impact-resistant with a matte finish. Handles heat up to about 87 °C. Our standard material.', 'متينة ومقاومة للصدمات بلمسة مطفية. تتحمل الحرارة حتى حوالي 87 درجة. خامتنا الأساسية.', 0.11, 1.04, 'fdm', 270, 90, 85, '[{"code":"black","name_en":"Black","name_ar":"أسود","hex":"#1E1F22","in_stock":true},{"code":"white","name_en":"White","name_ar":"أبيض","hex":"#F2F2EE","in_stock":true},{"code":"grey","name_en":"Silver grey","name_ar":"رمادي","hex":"#8A8F96","in_stock":true},{"code":"red","name_en":"Red","name_ar":"أحمر","hex":"#C8232C","in_stock":true},{"code":"blue","name_en":"Blue","name_ar":"أزرق","hex":"#2350B8","in_stock":true},{"code":"yellow","name_en":"Yellow","name_ar":"أصفر","hex":"#F4C21B","in_stock":true}]', 1), ('ASA', 'ASA (outdoor)', 'ASA (للخارج)', 'Like ABS but resists sunlight and weather. Handles heat up to about 100 °C. Best for balconies, gardens and cars.', 'مثل ABS لكنها تقاوم الشمس والطقس. تتحمل الحرارة حتى حوالي 100 درجة. الأفضل للشرفات والحدائق والسيارات.', 0.16, 1.07, 'fdm', 270, 90, 100, '[{"code":"white","name_en":"White","name_ar":"أبيض","hex":"#F2F2EE","in_stock":true},{"code":"black","name_en":"Black","name_ar":"أسود","hex":"#1E1F22","in_stock":true}]', 2) on conflict (code) do update set colors = excluded.colors, price_per_gram = excluded.price_per_gram;
