-- Reference data (prices, taxes, zones, currencies, categories, materials)
-- Printer types: choosing a type fills in bed size, nozzle, temperatures, slots, connection and the helper app.
on conflict (code) do update set bed = excluded.bed, slicer_app = excluded.slicer_app, slicer_url = excluded.slicer_url, notes_en = excluded.notes_en, notes_ar = excluded.notes_ar;

select 'Bambu Lab P2S Combo', 'bambu_p2s', '["ABS","ASA"]', '[{"slot":1,"material":"ABS","color":"black"},{"slot":2,"material":"ABS","color":"white"},{"slot":3,"material":"ABS","color":"grey"},{"slot":4,"material":"ASA","color":"white"}]', false
where not exists (select 1 from public.printers);
